/** M74 operator-only controls. Imports never connect or migrate. */
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import {readMigrationManifest} from '../../packages/neuvetra-database/src/staging-migrations'
import type {WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
import {hashManifestValue} from './create-source-manifest'
import {PROJECT} from './m73-common'
export {PROJECT,sha,exclusiveJson,operatorUrl,connectOperator,inventory,runtimeSafe,sameRows,sameCatalog,lockedTables,ROLE_SQL,MEMBERS_SQL,DEFAULT_SQL,type Inventory} from './m73-common'
export const BASELINE_MANIFEST_SHA256='baecb8858475cdf1d57b38af4539b5f5ad97a973223ce17284125af214d85e86'
// Coordinator candidate1 author pin; independent exact-byte review and hosted gate remain separate.
export const MIGRATION='4486f83e2f2f6e5cb8db5991575a74f540b891eefd1ff65317801545c5b6c071'
export const MIGRATION_NAME='0017_mobile_diesel.sql'
export const NEW_TABLES=['mobile_diesel_audit','mobile_diesel_evidence_reservations','mobile_diesel_fuel_statements','mobile_diesel_heads','mobile_diesel_mileage_statements','mobile_diesel_reports','mobile_diesel_requests','mobile_diesel_reviews','mobile_diesel_versions'] as const
export function requireValue(value:unknown,message='M74 gate refused'):asserts value {if(!value)throw Error(message)}
export function localName(name:string,port:number){requireValue(/^m74_(ops|qa|security)_[a-z0-9_]+$/.test(name)&&[55463,55472].includes(port))}
export function connectLocal(name:string,port=55463){localName(name,port);return createPostgresConnection(`postgres://${port===55472?'supabase_admin':'m63_test_admin'}@127.0.0.1:${port}/`+name,{maxConnections:1,tls:false})}
export async function canonicalReceipts(tx:WorkspaceSql,version:16|17){
 const manifest=await readMigrationManifest()
 requireValue([16,17].includes(manifest.length)&&hashManifestValue(manifest.slice(0,16).map(({name,sha256})=>({name,sha256})))===BASELINE_MANIFEST_SHA256)
 if(version===17)requireValue(/^[a-f0-9]{64}$/.test(MIGRATION)&&manifest.length===17&&manifest[16]?.name===MIGRATION_NAME&&manifest[16]?.sha256===MIGRATION)
 const receipts=(await tx.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows
 requireValue(receipts.length===version&&receipts.every((r,i)=>r.name===manifest[i]?.name&&r.sha256===manifest[i]?.sha256))
 const target=(await tx.query<{project_ref:string;profile:string}>('select project_ref,profile from neuvetra.staging_target')).rows
 requireValue(target.length===1&&target[0]?.project_ref===PROJECT&&target[0]?.profile==='neuvetra.private-synthetic-staging.v1')
 return manifest
}

/** Independent byte inventory, not an application renderer or an accounting replay.
 * Must be produced in the same snapshot as the dump. Contains fingerprints, never statement content.
 */
import type {WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
import {canonicalManifestJson,hashManifestValue} from './create-source-manifest'
import {sha,requireValue} from './m74-common'
export interface RecoveryEntry {table:string;id:string;part:string;sha256:string;byteLength:number}
export interface RecoveryManifest {profile:'neuvetra.m74.recovery-content.v1';schemaVersion:16|17;entries:RecoveryEntry[];sha256:string}
export function byteEntry(table:string,id:string,part:string,bytes:string|Uint8Array,expectedHash?:string,expectedLength?:number):RecoveryEntry {
 const content=typeof bytes==='string'?Buffer.from(bytes,'utf8'):bytes
 const digest=sha(content);requireValue(expectedHash===undefined||digest===expectedHash,'Stored content hash mismatch')
 requireValue(expectedLength===undefined||content.byteLength===expectedLength,'Stored content length mismatch')
 return {table,id,part,sha256:digest,byteLength:content.byteLength}
}
export async function recoveryManifest(tx:WorkspaceSql,schemaVersion:16|17):Promise<RecoveryManifest>{
 const entries:RecoveryEntry[]=[]
 for(const table of ['electricity_sources','worksheet_reports','source_worksheet_reports','annual_electricity_reports','annual_evidence_reports']){
  const source=table==='electricity_sources',column=source?'original_bytes':'report_bytes',hash=source?'sha256':'report_sha256',length=source?'byte_length':'report_byte_length'
  for(const row of (await tx.query<{id:string;content:string;hash:string;length:number}>(`select id,encode(${column},'hex') content,${hash} hash,${length} length from neuvetra.${table} order by id`)).rows)
   entries.push(byteEntry(table,row.id,'download',Buffer.from(row.content,'hex'),row.hash,Number(row.length)))
 }
 const methods=['stationary_gas',...(schemaVersion===17?['mobile_diesel']:[])]
 const statementTables=['stationary_gas_statements',...(schemaVersion===17?['mobile_diesel_fuel_statements','mobile_diesel_mileage_statements']:[])]
 for(const table of statementTables){
  for(const row of (await tx.query<{id:string;statement_text:string;statement_sha256:string;payload:unknown}>(`select id,statement_text,statement_sha256,payload from neuvetra.${table} order by id`)).rows){
   entries.push(byteEntry(table,row.id,'statement',row.statement_text,row.statement_sha256))
   entries.push(byteEntry(table,row.id,'metadata',canonicalManifestJson(row.payload)))
  }
 }
 for(const table of ['corporate_inventory_versions',...methods.map(m=>m+'_versions')]){
  for(const row of (await tx.query<{id:string;export_text:string;payload:Record<string,unknown>}>(`select id,export_text,payload from neuvetra.${table} order by id`)).rows){
   entries.push(byteEntry(table,row.id,'export',row.export_text))
   if(table!=='corporate_inventory_versions'){
    requireValue(Object.hasOwn(row.payload,'calculation'),'Missing calculation property')
    // Explicit null is fingerprinted as null, never silently excluded or converted to zero.
    entries.push(byteEntry(table,row.id,'calculation',canonicalManifestJson(row.payload.calculation)))
   }
  }
 }
 for(const table of methods.map(m=>m+'_reports')){
  for(const row of (await tx.query<{id:string;payload:{html:string;htmlSha256:string;htmlByteLength:number;snapshotJson:string;snapshotSha256:string}}>(`select id,payload from neuvetra.${table} order by id`)).rows){
   const p=row.payload;requireValue(typeof p.html==='string'&&typeof p.snapshotJson==='string')
   entries.push(byteEntry(table,row.id,'html',p.html,p.htmlSha256,p.htmlByteLength))
   entries.push(byteEntry(table,row.id,'snapshot',p.snapshotJson,p.snapshotSha256))
  }
 }
 entries.sort((a,b)=>canonicalManifestJson(a).localeCompare(canonicalManifestJson(b)))
 return {profile:'neuvetra.m74.recovery-content.v1',schemaVersion,entries,sha256:hashManifestValue(entries)}
}
export function validateRecoveryManifest(value:RecoveryManifest){
 requireValue(value.profile==='neuvetra.m74.recovery-content.v1'&&[16,17].includes(value.schemaVersion)&&Array.isArray(value.entries))
 requireValue(value.entries.every(e=>typeof e.table==='string'&&typeof e.id==='string'&&typeof e.part==='string'&&/^[a-f0-9]{64}$/.test(e.sha256)&&Number.isSafeInteger(e.byteLength)&&e.byteLength>=0))
 requireValue(new Set(value.entries.map(e=>JSON.stringify([e.table,e.id,e.part]))).size===value.entries.length)
 requireValue(value.sha256===hashManifestValue(value.entries))
}
export function sameRecovery(before:RecoveryManifest,after:RecoveryManifest,allowNewEmptySchema=false){
 validateRecoveryManifest(before);validateRecoveryManifest(after)
 requireValue(before.schemaVersion===after.schemaVersion||(allowNewEmptySchema&&before.schemaVersion===16&&after.schemaVersion===17))
 requireValue(hashManifestValue(before.entries)===hashManifestValue(after.entries),'Recovery bytes differ')
}

/** JSON stdin {operatorDatabaseUrl}; args pg_dump.exe archive.dpapi receipt.json 16|17. */
import {connectOperator,operatorUrl,canonicalReceipts,inventory,exclusiveJson,sha,requireValue,PROJECT,runtimeSafe} from './m74-common'
import {recoveryManifest} from './m74-recovery-manifest'
import {resolve} from 'node:path'
export async function createApplicationBundle(db:Awaited<ReturnType<typeof connectOperator>>,pgDump:string,env:Record<string,string|undefined>,schemaVersion:16|17){
 return db.transaction(async tx=>{
  const createdAt=new Date().toISOString()
  await tx.exec('set transaction isolation level repeatable read read only');await canonicalReceipts(tx,schemaVersion);await runtimeSafe(tx)
  // Exported snapshot binds dump, fingerprints and dependencies to the same MVCC state.
  const snapshot=(await tx.query<{snapshot:string}>('select pg_export_snapshot() snapshot')).rows[0]!.snapshot
  const baseline=await inventory(tx),recovery=await recoveryManifest(tx,schemaVersion)
  requireValue(baseline.dependencies.every(d=>d.schema==='auth'&&d.relation==='users'))
  const refs=(await tx.query<{table_name:string;column_name:string}>("select c.relname table_name,a.attname column_name from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=k.conkey[1] where n.nspname='neuvetra' and k.contype='f' and k.confrelid='auth.users'::regclass and cardinality(k.conkey)=1 order by 1,2")).rows
  requireValue(refs.length&&refs.every(r=>/^[a-z_]+$/.test(r.table_name)&&/^[a-z_]+$/.test(r.column_name)))
  const subjects=(await tx.query<{id:string}>('select distinct id from ('+refs.map(r=>`select ${r.column_name} id from neuvetra.${r.table_name}`).join(' union all ')+') u where id is not null order by id')).rows.map(r=>r.id)
  requireValue(subjects.every(id=>/^[0-9a-f-]{36}$/.test(id)))
  const uid=(await tx.query<{definition:string}>("select pg_get_functiondef('auth.uid()'::regprocedure) definition")).rows[0]!.definition
  const child=Bun.spawn([pgDump,'--format=custom','--no-password','--schema=neuvetra','--snapshot='+snapshot],{env,stdout:'pipe',stderr:'pipe'})
  const [dump,,code]=await Promise.all([new Response(child.stdout).arrayBuffer(),new Response(child.stderr).text(),child.exited]);requireValue(code===0&&dump.byteLength>16)
  return {profile:'neuvetra.m74.application-recovery.v1',project:PROJECT,createdAt,schemaVersion,inventory:baseline,recoveryManifest:recovery,dependencies:{authUserIds:subjects,authUidDefinition:uid,providerRecovery:'excluded: users are UUID dependency stubs only; no credentials, sessions, provider configuration or storage objects'},dumpSha256:sha(new Uint8Array(dump)),dumpBase64:Buffer.from(dump).toString('base64')}
 })
}
async function main(){
let db:Awaited<ReturnType<typeof connectOperator>>|undefined,stage='configuration'
try{
 const [pgDump,archive,receipt,versionText]=process.argv.slice(2);const schemaVersion=Number(versionText);requireValue(schemaVersion===16||schemaVersion===17);requireValue(pgDump&&archive&&receipt&&!await Bun.file(archive).exists()&&!await Bun.file(receipt).exists())
 const input=JSON.parse(await Bun.stdin.text()),url=operatorUrl(input.operatorDatabaseUrl)
 const env=Object.fromEntries(Object.entries(process.env).filter(([key])=>!key.toUpperCase().startsWith('PG')))
 Object.assign(env,{PGHOST:url.hostname,PGPORT:url.port,PGDATABASE:'postgres',PGUSER:decodeURIComponent(url.username),PGPASSWORD:decodeURIComponent(url.password),PGSSLMODE:'verify-full',PGSSLROOTCERT:resolve('tools/cloud/fixtures/supabase-prod-ca-2021.crt'),PGCONNECT_TIMEOUT:'15'})
 db=await connectOperator(input.operatorDatabaseUrl)
 stage='snapshot_and_dump'
 const bundle=await createApplicationBundle(db,pgDump,env,schemaVersion)
 stage='encrypt'
 const child=Bun.spawn(['powershell.exe','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',resolve('tools/staging/m74-seal-backup.ps1'),'-ArchivePath',resolve(archive)],{stdin:'pipe',stdout:'pipe',stderr:'pipe'});await child.stdin.write(JSON.stringify(bundle));await child.stdin.end()
 const [sealed,,code]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);requireValue(code===0&&JSON.parse(sealed).status==='m74_bundle_sealed')
 stage='receipt'
 await exclusiveJson(receipt,{status:'m74_encrypted_application_backup',createdAt:bundle.createdAt,project:PROJECT,schemaVersion,archiveSha256:sha(new Uint8Array(await Bun.file(archive).arrayBuffer())),dumpSha256:bundle.dumpSha256,inventory:bundle.inventory,recoveryManifest:bundle.recoveryManifest,protection:'DPAPI CurrentUser; same Windows identity and profile required',scope:'neuvetra schema/data/owners/ACLs plus Auth UUID/uid dependencies; Supabase Auth/provider recovery excluded',restoreDrill:'pending'})
 console.log(JSON.stringify({status:'m74_encrypted_application_backup',schemaVersion,tables:bundle.inventory.tables.length}))
}catch{console.error(JSON.stringify({status:'m74_backup_failed',stage}));process.exitCode=1}finally{await db?.close()}

}
if(import.meta.main)await main()

param(
 [ValidateSet('Seal','Restore')][string]$Mode='Seal',
 [Parameter(Mandatory=$true)][string]$ArchivePath,
 [string]$PgRestorePath,
 [string]$DatabaseName,
 [string]$ReceiptPath,
 [ValidateSet(55463,55472)][int]$Port=55472
)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Security
try {
 $target=[IO.Path]::GetFullPath($ArchivePath)
 $hasher=[Security.Cryptography.SHA256]::Create()
 if($Mode -eq 'Seal'){
  $content=[Text.Encoding]::UTF8.GetBytes([Console]::In.ReadToEnd())
  if($content.Length -lt 100){throw 'empty bundle'}
  $protected=[Security.Cryptography.ProtectedData]::Protect($content,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
  $stream=[IO.File]::Open($target,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
  try{$stream.Write($protected,0,$protected.Length);$stream.Flush($true)}finally{$stream.Dispose()}
  $restored=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($target),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
  if([Convert]::ToBase64String($hasher.ComputeHash($content)) -ne [Convert]::ToBase64String($hasher.ComputeHash($restored))){throw 'mismatch'}
  Write-Output '{"status":"m74_bundle_sealed"}'
 }else{
  if($DatabaseName -notmatch '^m74_(ops|qa|security)_[a-z0-9_]+$' -or -not $PgRestorePath -or -not $ReceiptPath -or (Test-Path -LiteralPath $ReceiptPath)){throw 'target refused'}
  $bytes=[IO.File]::ReadAllBytes($target)
  $hash=[BitConverter]::ToString($hasher.ComputeHash($bytes)).Replace('-','').ToLowerInvariant()
  $bundle=[Text.Encoding]::UTF8.GetString([Security.Cryptography.ProtectedData]::Unprotect($bytes,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser))
  $start=New-Object Diagnostics.ProcessStartInfo
  $start.FileName=(Get-Command bun).Source
  $script=Join-Path $PSScriptRoot 'm74-restore.ts'
  foreach($arg in @($PgRestorePath,$ReceiptPath)){if($arg.Contains('"') -or $arg.Contains("`n") -or $arg.Contains("`r")){throw 'invalid path'}}
  $start.Arguments='run "'+$script+'" "'+[IO.Path]::GetFullPath($PgRestorePath)+'" '+$DatabaseName+' "'+[IO.Path]::GetFullPath($ReceiptPath)+'" '+$hash+' '+$Port
  $start.UseShellExecute=$false;$start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $process=[Diagnostics.Process]::Start($start)
  $stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync()
  $process.StandardInput.Write($bundle);$process.StandardInput.Close();$process.WaitForExit()
  Write-Output $stdout.Result
  if($process.ExitCode -ne 0){throw 'restore failed'}
 }
}catch{Write-Output ('{"status":"m74_bundle_operation_failed","mode":"'+$Mode+'"}');exit 1}

/** Only launched by m74-seal-backup.ps1 Restore mode. New loopback database; no reset or global role edits. */
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import {connectLocal,canonicalReceipts,inventory,exclusiveJson,sha,requireValue,sameRows,sameCatalog,ROLE_SQL,MEMBERS_SQL,PROJECT,runtimeSafe} from './m74-common'
import {recoveryManifest,sameRecovery,validateRecoveryManifest} from './m74-recovery-manifest'
import {hashManifestValue} from './create-source-manifest'
let db:ReturnType<typeof connectLocal>|undefined,admin:ReturnType<typeof createPostgresConnection>|undefined,stage='configuration'
try{
 const [pgRestore,name,receipt,archiveSha256,portText='55472']=process.argv.slice(2);const port=Number(portText);requireValue([55463,55472].includes(port)&&pgRestore&&name&&receipt&&/^[a-f0-9]{64}$/.test(archiveSha256??'')&&!await Bun.file(receipt).exists()&&/^m74_(ops|qa|security)_[a-z0-9_]+$/.test(name))
 const bundle=JSON.parse(await Bun.stdin.text());requireValue(bundle.profile==='neuvetra.m74.application-recovery.v1'&&bundle.project===PROJECT&&[16,17].includes(bundle.schemaVersion))
 validateRecoveryManifest(bundle.recoveryManifest);requireValue(bundle.recoveryManifest.schemaVersion===bundle.schemaVersion)
 requireValue(!bundle.inventory.memberships.some((r:any)=>r.member==='neuvetra_runtime'))
 const dump=Buffer.from(bundle.dumpBase64,'base64');requireValue(sha(dump)===bundle.dumpSha256)
 requireValue(!bundle.inventory.defaultAcls.some((r:any)=>r.schema==='*'||r.schema==='neuvetra'))
 admin=createPostgresConnection(`postgres://${port===55472?'supabase_admin':'m63_test_admin'}@127.0.0.1:${port}/postgres`,{maxConnections:1,tls:false})
 stage='roles_and_new_database'
 const roles=(await admin.query<{rolname:string}>(ROLE_SQL)).rows
 if(port===55472){requireValue(hashManifestValue(roles)===hashManifestValue(bundle.inventory.roles));requireValue(hashManifestValue((await admin.query(MEMBERS_SQL)).rows)===hashManifestValue(bundle.inventory.memberships))}
 // Cluster roles are prerequisites, never modified by this drill. Provider privilege differences are reported separately.
 for(const role of bundle.inventory.roles as {rolname:string}[]) if(['postgres','anon','authenticated','neuvetra_runtime'].includes(role.rolname))requireValue(roles.some(r=>r.rolname===role.rolname))
 requireValue((await admin.query('select 1 from pg_database where datname=$1',[name])).rows.length===0)
 await admin.exec(`create database ${name} template template0`);db=connectLocal(name,port)
 // PostgreSQL template defaults are local prerequisites; application runtime must not gain CREATE through PUBLIC.
 await db.exec('revoke create on schema public from public')
 stage='auth_dependency_stubs'
 requireValue(bundle.dependencies.authUserIds.every((id:unknown)=>typeof id==='string'&&/^[0-9a-f-]{36}$/.test(id)))
 // Archive is trusted operator data, not fetched content. Restore itself necessarily executes trusted DDL.
 await db.exec('create schema auth; create table auth.users(id uuid primary key); grant usage on schema auth to postgres,authenticated,neuvetra_runtime;')
 for(const id of bundle.dependencies.authUserIds)await db.query('insert into auth.users(id) values($1)',[id])
 await db.exec(bundle.dependencies.authUidDefinition)
 stage='restore_exact_archive'
 const env=Object.fromEntries(Object.entries(process.env).filter(([key])=>!key.toUpperCase().startsWith('PG')))
 Object.assign(env,{PGHOST:'127.0.0.1',PGPORT:String(port),PGDATABASE:name,PGUSER:port===55472?'supabase_admin':'m63_test_admin',PGSSLMODE:'disable',PGCONNECT_TIMEOUT:'10'})
 const child=Bun.spawn([pgRestore,'--exit-on-error','--single-transaction','--no-password','--dbname='+name],{env,stdin:'pipe',stdout:'pipe',stderr:'pipe'});await child.stdin.write(dump);await child.stdin.end()
 const [,,code]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);requireValue(code===0)
 stage='verify_rows_catalog'
 const restored=await db.transaction(async tx=>{await tx.exec('set transaction isolation level repeatable read read only');await canonicalReceipts(tx,bundle.schemaVersion);return inventory(tx)})
 const recoveredContent=await db.transaction(tx=>recoveryManifest(tx,bundle.schemaVersion));sameRecovery(bundle.recoveryManifest,recoveredContent)
 sameRows(bundle.inventory,restored);sameCatalog(bundle.inventory,restored);requireValue(bundle.inventory.tables.length===restored.tables.length);requireValue(JSON.stringify(bundle.inventory.metadata)===JSON.stringify(restored.metadata))
 requireValue(!restored.defaultAcls.some((r:any)=>r.schema==='*'||r.schema==='neuvetra'))
 const runtimeBefore=bundle.inventory.roles.find((r:any)=>r.rolname==='neuvetra_runtime'),runtimeAfter=restored.roles.find((r:any)=>r.rolname==='neuvetra_runtime');requireValue(JSON.stringify(runtimeBefore)===JSON.stringify(runtimeAfter))
 requireValue(!restored.memberships.some((r:any)=>r.member==='neuvetra_runtime'));await runtimeSafe(db)
 const allRoleFlagsAndMembershipsExact=hashManifestValue(bundle.inventory.roles)===hashManifestValue(restored.roles)&&hashManifestValue(bundle.inventory.memberships)===hashManifestValue(restored.memberships)
 if(port===55472)requireValue(allRoleFlagsAndMembershipsExact)
 // Actual SET ROLE exercises the restored effective read boundary, without an Auth claim.
 await db.transaction(async tx=>{await tx.exec('set local role neuvetra_runtime');requireValue((await tx.query('select * from neuvetra.companies')).rows.length===0)})
 const actor=(await db.query<{user_id:string}>("select a.user_id from neuvetra.staging_access a join neuvetra.company_members m on m.user_id=a.user_id and m.company_id=a.company_id where a.active order by a.user_id limit 1")).rows[0];requireValue(actor)
 await db.transaction(async tx=>{await tx.exec('set local role neuvetra_runtime');await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor.user_id]);requireValue((await tx.query('select * from neuvetra.companies')).rows.length===1)})
 await exclusiveJson(receipt,{status:'m74_exact_application_archive_restored',createdAt:new Date().toISOString(),project:PROJECT,database:name,port,schemaVersion:bundle.schemaVersion,sourceBackupCreatedAt:bundle.createdAt,recoveryManifest:recoveredContent,recoveryContentExact:true,archiveSha256,dumpSha256:bundle.dumpSha256,applicationRowsAndCatalogExact:true,runtimeRoleFlagsExact:true,allRoleFlagsAndMembershipsExact,applicationDefaultAclsExact:true,runtimeNoClaimDenied:true,runtimeExistingActorReadPassed:true,inventory:restored,sourceRoles:bundle.inventory.roles,sourceMemberships:bundle.inventory.memberships,sourceDefaultAcls:bundle.inventory.defaultAcls,providerRecovery:'NOT VERIFIED: local auth.users UUID stubs; actual Auth accounts/sessions/provider config/storage excluded; role passwords omitted',failedDatabasePolicy:'New clone retained; never reset or drop existing data'})
 console.log(JSON.stringify({status:'m74_exact_application_archive_restored',database:name,tables:restored.tables.length}))
}catch{console.error(JSON.stringify({status:'m74_restore_failed',stage,newCloneMayRemain:true}));process.exitCode=1}finally{await db?.close();await admin?.close()}

import type {WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
import {auditLegacyStagingExposure} from '../../packages/neuvetra-database/src/staging-audit'
import {canonicalReceipts,inventory,lockedTables,sameRows,sameCatalog,requireValue,MIGRATION,MIGRATION_NAME,NEW_TABLES,runtimeSafe,type Inventory} from './m74-common'
import {recoveryManifest,sameRecovery,type RecoveryManifest} from './m74-recovery-manifest'
import {hashManifestValue} from './create-source-manifest'
/** Caller must use a transaction; injection permits native offline verification only. */
export async function applyExact17(tx:WorkspaceSql,baseline:Inventory,contentBaseline:RecoveryManifest){
  await tx.query('select pg_advisory_xact_lock(630009)')
  await lockedTables(tx)
  const manifest=await canonicalReceipts(tx,16)
  await runtimeSafe(tx)
  requireValue((await auditLegacyStagingExposure(tx)).legacyContainmentVerified)
  const before=await inventory(tx),beforeContent=await recoveryManifest(tx,16)
  sameRecovery(contentBaseline,beforeContent)
  requireValue(hashManifestValue(before)===hashManifestValue(baseline))
  requireValue(/^[a-f0-9]{64}$/.test(MIGRATION)&&manifest.length===17&&manifest[16]?.name===MIGRATION_NAME&&manifest[16]?.sha256===MIGRATION)
  await tx.exec(manifest[16]!.sql)
  await tx.query('insert into neuvetra.schema_migrations(name,sha256) values($1,$2)',[manifest[16]!.name,MIGRATION])
  await canonicalReceipts(tx,17)
  await runtimeSafe(tx)
  const after=await inventory(tx)
  const afterContent=await recoveryManifest(tx,17);sameRecovery(beforeContent,afterContent,true)
  sameRows(before,after,true)
  sameCatalog(before,after,true)
  // No old row may change, including duplicate multiplicity. Only one new migration receipt is expected.
  for(const old of before.tables){const now=after.tables.find(t=>t.name===old.name)!;requireValue(now.count===old.count+(old.name==='schema_migrations'?1:0))}
  requireValue(after.tables.length===before.tables.length+NEW_TABLES.length&&NEW_TABLES.every(name=>!before.tables.some(t=>t.name===name)&&after.tables.some(t=>t.name===name&&t.count===0)))
